        // ── NAVIGATION ────────────────────────────────────────────────────────

        private static string FormatMachineName(string? manufacturer, string? model) => DisplayFormat.MachineName(manufacturer, model);

        private static string ExtractNavTag(object? tag)
            => tag is object[] arr && arr.Length >= 1 ? (arr[0]?.ToString() ?? "") : (tag?.ToString() ?? "");

        private async void NavBtn_Click(object sender, RoutedEventArgs e)
        {
            if (sender is Button btn) await NavigateTo(ExtractNavTag(btn.Tag));
        }

        private async void NavStackPanel_PreviewMouseLeftButtonDown(object sender, System.Windows.Input.MouseButtonEventArgs e)
        {
            var el = e.OriginalSource as DependencyObject;
            int guard = 0;
            while (el != null && guard++ < 15)
            {
                if (el is Button btn && btn.Tag != null)
                {
                    string tag = ExtractNavTag(btn.Tag);
                    if (!string.IsNullOrEmpty(tag))
                    {
                        e.Handled = true; // preventing this from ALSO firing via Button.Click later (double-nav)
                        await NavigateTo(tag);
                        return;
                    }
                }
                el = System.Windows.Media.VisualTreeHelper.GetParent(el);
            }
        }

        private async Task NavigateTo(string panel)
        {
            var navSw = System.Diagnostics.Stopwatch.StartNew();

            // Cancel any in-progress navigation immediately so user can switch pages freely
            _navCts?.Cancel();
            _navCts?.Dispose();
            _navCts = new CancellationTokenSource();
            var ct = _navCts.Token;

            _isNavigating = true;
            HideLoading();

            try
            {
                // Use cached dictionaries built at Loaded time
                if (_navPanels == null || _navBtns == null) return;

                foreach (var p in _navPanels.Values) p.Visibility = Visibility.Collapsed;
                foreach (var b in _navBtns.Values)   b.Style = _navStyleNormal;

                if (panel != "Battery")
                {
                    if (_batTimer.IsEnabled) _batTimer.Stop();
                    StopAppDrainAutoRefresh();
                }

                // Stop dashboard background ping when leaving Dashboard (saves bandwidth + CPU)
                if (panel != "Dashboard" && _dashPingCts != null && !_dashPingCts.IsCancellationRequested)
                {
                    _dashPingCts.Cancel();
                }

                // Stop refreshing the process table when leaving the RAM page
                if (panel != "Ram") StopRamProcTimer();
                // the Stress page process timer
                if (panel != "Stress") StopStressProcTimer();

                if (_navPanels.TryGetValue(panel, out var active))
                {
                    EnsurePanelWpfUiTheme(active as FrameworkElement);   // the WPF-UI theme is applied on first display / after a theme change
                    active.Visibility = Visibility.Visible;
                    active.Opacity    = 1; // the unconditional source of truth — see the reason below
                    if (active is FrameworkElement fe)
                    {
                        fe.RenderTransform = System.Windows.Media.Transform.Identity;
                        if (Fx.Motion)
                        {
                            var ease = new System.Windows.Media.Animation.CubicEase { EasingMode = System.Windows.Media.Animation.EasingMode.EaseOut };
                            var fadeIn = new System.Windows.Media.Animation.DoubleAnimation(0, 1, TimeSpan.FromMilliseconds(140)) { EasingFunction = ease };
                            fe.BeginAnimation(UIElement.OpacityProperty, fadeIn, System.Windows.Media.Animation.HandoffBehavior.SnapshotAndReplace);
                            // and a few pixels of slide up: the new page settles in
                            var slide = new System.Windows.Media.TranslateTransform(0, 8);
                            fe.RenderTransform = slide;
                            var up = new System.Windows.Media.Animation.DoubleAnimation(8, 0, TimeSpan.FromMilliseconds(180)) { EasingFunction = ease };
                            up.Completed += (_, _) => { if (fe.RenderTransform == slide) fe.RenderTransform = System.Windows.Media.Transform.Identity; };
                            slide.BeginAnimation(System.Windows.Media.TranslateTransform.YProperty, up);
                        }
                        else fe.BeginAnimation(UIElement.OpacityProperty, null);
                        AnimateCardsIn(fe);   // the cards appear one after another
                    }
                    if (_themeDirtyPanels.Remove(panel))
                    {
                        var panelToRefresh = active;
                        _ = Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded,
                            new Action(() =>
                            {
                                // Safety net: an error in the visual refresh must not stop the application.
                                try { RefreshThemeVisualsInSubtree(panelToRefresh); }
                                catch (Exception ex) { AppLogger.Warning(ex, $"RefreshThemeVisuals({panel})"); }
                            }));
                    }
                }
                if (_navBtns.TryGetValue(panel, out var activeBtn))
                {
                    activeBtn.Style = _navStyleActive;
                    // Update per-page accent color for the active nav button
                    SMDWin.Services.ThemeManager.SetNavPageAccent(panel, Application.Current.Resources);
                    HighlightActiveNavIcon(panel);
                }
                _currentPanel = panel;
                // Update breadcrumb
                UpdateBreadcrumb(panel);

                if (panel == "Settings")
                {
                    _ = Dispatcher.BeginInvoke(new Action(() =>
                    {
                        try
                        {
                            HighlightActiveThemeButton(SettingsService.Current.ThemeName, SettingsService.Current.AutoTheme);
                            HighlightActiveAccentButton(SettingsService.Current.AccentName ?? "Blue");
                        }
                        catch (Exception ex) { AppLogger.Debug($"HighlightActiveThemeButton@Settings nav: {ex.Message}"); }
                    }), System.Windows.Threading.DispatcherPriority.Loaded);
                }

                if (panel == "Stress")
                {
                    double realElapsedSec = _appStartStopwatch.Elapsed.TotalSeconds;
                    AppLogger.Info($"S2-DIAG ChartBuffer @ Stress enter: chartIdx={_chartIdx}, " +
                        $"rangeSelectat={ChartPoints}s, realElapsedSecDeLaStart={realElapsedSec:F0}s, " +
                        $"raport(chartIdx/realElapsedSec)={(realElapsedSec > 0 ? _chartIdx / realElapsedSec : 0):F2} " +
                        $"(should be ~1.00 if each slot = 1 real second; below 1 means" +
                        $"that ticks were missed — throttling on excluded pages or a minimized window)");
                }

                try
                {
                    // smooth render timer needed on Stress (charts) and Dashboard (ping + sparklines)
                    if (panel == "Stress" || panel == "Dashboard")
                    {
                        if (!_smoothRenderTimer.IsEnabled) _smoothRenderTimer.Start();
                    }
                    else
                    {
                        if (_smoothRenderTimer.IsEnabled) _smoothRenderTimer.Stop();
                    }

                    if (_gpuStressTimer != null)
                    {
                        if (panel == "Stress") { if (!_gpuStressTimer.IsEnabled) _gpuStressTimer.Start(); }
                        else                   { if (_gpuStressTimer.IsEnabled)  _gpuStressTimer.Stop();  }
                    }

                    if (panel != "Network") StopNetPageTimer();
                    if (panel != "Disk")    StopStorageTempTimer();

                    switch (panel)
                    {
                        case "Dashboard":
                            if (DashboardSkeleton != null)
                                DashboardSkeleton.Visibility = (_summary == null || string.IsNullOrEmpty(_summary.OsName))
                                    ? Visibility.Visible : Visibility.Collapsed;
                            await LoadDashboardAsync();
                            if (DashStorageGrid != null && DashStorageGrid.Children.Count == 0)
                                _ = Task.Run(() => Dispatcher.InvokeAsync(() => PopulateDashStorageGridAsync()));
                            // Reset the dashboard clock index — avoid showing old data on return
                            _dashClockIdx = _chartIdx % ChartMaxPoints;
                            try
                            {
                                int nTail = Math.Min(5, _chartIdx);
                                var tailCpu = new System.Collections.Generic.List<string>();
                                var tailGpu = new System.Collections.Generic.List<string>();
                                for (int k = nTail - 1; k >= 0; k--)
                                {
                                    int idx = (_chartIdx - 1 - k + ChartMaxPoints) % ChartMaxPoints;
                                    tailCpu.Add(float.IsNaN(_chartCpu[idx]) ? "NaN" : _chartCpu[idx].ToString("F0"));
                                    tailGpu.Add(float.IsNaN(_chartGpu[idx]) ? "NaN" : _chartGpu[idx].ToString("F0"));
                                }
                                AppLogger.Debug($"Dashboard entry — _chartIdx={_chartIdx}, last CPU temps={string.Join(",", tailCpu)}, GPU temp={string.Join(",", tailGpu)}, _dvCache.Count={_dvCache.Count}, _slotDrawn.Count={_slotDrawn.Count}");
                            }
                            catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                            _ = Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded,
                                new Action(UpdateDashCardHeights));
                            _ = Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.ApplicationIdle,
                                new Action(UpdateDashCardHeights));
                            _ = Dispatcher.InvokeAsync(UpdateDashCardHeights,
                                System.Windows.Threading.DispatcherPriority.Loaded);
                            _ = Task.Delay(200).ContinueWith(_ =>
                                Dispatcher.InvokeAsync(UpdateDashCardHeights));
                            break;
                        case "SysInfo":   await ShowSysInfoPageAsync(); break;
                        case "Crash":     await LoadCrashesInternalAsync(); break;
                        case "Events":
                            InitPerfmonEventsOverlay();
                            await RunEventScan();
                            break;
                        case "Stress":
                            _drawnIdxTempChart = _drawnIdxSingleCpu = _drawnIdxSingleGpu =
                            _drawnIdxCpuFreq = _drawnIdxCpuUsage = _drawnIdxGpuLoad = -1;
                            _dvCache.Clear();
                            StartStressProcTimer();
                            break;
                        case "Drivers":   await LoadAllDriversInternalAsync(); break;
                        case "Disk":
                            await LoadDisksInternalAsync();
                            LoadStorageAdvancedAsync();
                            StartStorageTempTimer();
                            break;
                        case "Ram":
                            await LoadRamPageAsync();
                            break;
                        case "Benchmark":
                            EnsureBenchmarkPage();
                            break;
                        case "Network":
                            await LoadNetworkAsync(); EnsurePublicIpLoaded();
                            StartNetPageTimer(); RefreshTopApps(true); break;
                        case "Apps":      await LoadAppsInternalAsync(); break;
                        case "Services":  await LoadKeyServicesAsync(); break;
                        case "Processes":
                            await RefreshProcessesAsync();
                            await Dispatcher.InvokeAsync(() =>
                            {
                                if (!_procTimer.IsEnabled)
                                {
                                    int secs = Math.Max(1, SettingsService.Current.ProcessRefreshSec);
                                    _procTimer.Interval = TimeSpan.FromSeconds(secs);
                                    _procTimer.Tick -= OnProcTick;
                                    _procTimer.Tick += OnProcTick;
                                    _procTimer.Start();
                                }
                            });
                            break;
                        case "Startup":    await LoadStartupAsync(useCache: true); break;
                        case "Battery":
                            await LoadBatteryAsync();
                            StartPowerCardsFit(); // the cards fill the rest of the window (MainWindow.PowerPage.cs)
                            StartAppDrainAutoRefresh();
                            LoadAdvancedPowerSection();
                            await Dispatcher.InvokeAsync(() =>
                            {
                                if (!_batTimer.IsEnabled)
                                {
                                    _batTimer.Interval = TimeSpan.FromSeconds(Math.Clamp(SettingsService.Current.BatteryRefreshSec, 5, 15));   // the power chart has at least one point every 15 s
                                    _batTimer.Tick -= OnBatTick;
                                    _batTimer.Tick += OnBatTick;
                                    _batTimer.Start();
                                }
                            });
                            break;
                        case "Tools":      InitShutdownPanel(); EnsureToolsPlus(); RefreshHibernateStatus(); RefreshSnapshotList(); RefreshToolActivity(); break;
                        case "PowerShell": LoadPsCommands(); break;
                    }
                }
                catch (OperationCanceledException) { HideLoading(); }
            }
            finally
            {
                if (!ct.IsCancellationRequested)
                    _isNavigating = false;
                else
                    _isNavigating = false;

                navSw.Stop();
                // every page open goes into the log (the first open is usually the slowest): compared across computers
                if (_pageOpenedOnce.Add(panel))
                    AppLogger.Info($"PAGE-TIMING {panel}: first opening {navSw.ElapsedMilliseconds} ms");
                else if (navSw.ElapsedMilliseconds > 300)
                    AppLogger.Info($"PAGE-TIMING {panel}: {navSw.ElapsedMilliseconds} ms");
                if (navSw.ElapsedMilliseconds > 2000)
                    AppLogger.Warning($"S24-DIAG NavigateTo(\"{panel}\") took {navSw.ElapsedMilliseconds}ms — far above the typical 400-800ms for other pages.");
            }
        }
        private readonly System.Collections.Generic.HashSet<string> _pageOpenedOnce = new();
    }
}
